config.script:

#The xTrace value give us the timestamp at the point the user clicked. We need to find the closest datapoint to where the user clicked

from java.util import Date

tStamp = self.props.xTrace.value
data = self.view.params.chartData
data = system.dataset.sort(data, 'Taken Date', True)

for row in range(1, data.rowCount):
	prevTakenDate = data.getValueAt(row-1, 'Taken Date')		
	takenDate = data.getValueAt(row, 'Taken Date')	
	if tStamp <= Date(takenDate.getTime()) and tStamp >= Date(prevTakenDate.getTime()):	# Return a java.util.date from java.sql.Timestamp
		if abs(system.date.millisBetween(tStamp, takenDate)) <= abs(system.date.millisBetween(tStamp, prevTakenDate)): 
			self.custom.excludePointTstamp = takenDate				
		else:
			self.custom.excludePointTstamp = prevTakenDate		

		params = {
					'values': {
							  "menuItems": [
								{
								  "menuItem": "Exclude Point"
								}						  ]
							}
				}

		position = {'top':event.pageY,'left':event.pageX}

		system.perspective.openPopup("confirm", view='Kanoa/Quality/Analysis/Popups/Context Menu/contextMenu', position=position, params=params, overlayDismiss=True, showCloseIcon=True)
		break

