customMethods.script:

	itemInfo = self.view.custom.itemInfo
#	selectMulti = self.view.custom.selectMulti
	plotOption = self.view.custom.plotOption

	def createAxis(name, min, max, showLabel=True):
#		buff = (max - min) * 0.01
#		min = min - buff
#		max = max + buff

		if name in axes:
			axes[name]['name'] = axes[name]['name']
			if min < axes[name]['min']: axes[name]['min'] = min 
			if max > axes[name]['max']: axes[name]['max'] = max 
		else:
			axes[name] = {
				"name": name,
				"min": min,
				"max": max,
				"alignment": "left",
				"width": 60,
				"label": {
					"visible": showLabel,
					"text": name,
					"offset": 0,
					"font": {
						"color": "",
						"size": 10
					},
					"style": {
						"classes": ""
					}
				},
				"tick": {
					"color": "",
					"count": "Auto",
					"label": {
						"format": "Auto",
						"font": {
							"color": "",
							"size": 10
						},
						"style": {
							"classes": ""
						}
					},
					"style": {
						"classes": ""
					}
				},
				"grid": {
					"visible": True,
					"color": "",
					"opacity": 0.3,
					"dashArray": 0,
					"style": {
						"classes": ""
					}
				},
				"style": {
					"classes": ""
				}
			}

	def createStyle(width=None, opacity=None):
		return {
			"stroke": {
				"color": "",
				"width": width,
				"opacity": opacity,
				"dashArray": None
			},
			"fill": {
				"color": "",
				"opacity": None
			}
		}

	def createColumn(name, color):
		return {
			"key": name,
			"color": color,
			"styles": {
				"normal": createStyle(),
				"highlighted": createStyle(2, 1),
				"selected": createStyle(),
				"muted": createStyle()
			}
		}

	def createTrend(axisName, columnName, columnColor):
		if not axisName in trends:
			trends[axisName] = {
				"visible": True,
				"type": "line",
				"series": "Checks",
				"interpolation": "curveLinear",
				"breakLine": False,
				"stack": True,
				"radius": 2,
				"axis": axisName,
				"columns": [],
				"baselines": []
			}

		trend = trends[axisName]['columns'].append(createColumn(columnName, columnColor))

	plotItemLists = {}

	if itemInfo is None: return

	plots = []
	itemCount = len(itemInfo.keys())
	colors = kanoa.core.utilities.colors.getColorList(itemCount)
	i = 0

	if plotOption == 'combine':
		plotItemLists["mainPlot"] = [item for item in itemInfo.values()]

		for plotItems in plotItemLists.values():
			axes = {}
			trends = {}

			for item in plotItems:
				name = 'mainAxis'

				min = item['min']
				max = item['max']

				label = item['label']
				unit = item['unit']
				color = colors[i]

				createAxis(name, min, max, False)

				createTrend(name, label, color)

				i += 1

			plots.append({
				"relativeWeight": 1,
				"trends": trends.values(),
				"axes": axes.values(),
				"markers": []
			})

		self.view.custom.plots = plots

		return

	if plotOption == 'separate':
		for item in itemInfo.values():
			plotItemLists[item['label']] = [item]

		for plotItems in plotItemLists.values():
			axes = {}
			trends = {}

			for item in plotItems:
				name = item['unit']

				min = item['min']
				max = item['max']

				label = item['label']
				unit = item['unit']
				color = colors[i]

				createAxis(name, min, max)

				createTrend(name, label, color)

				i += 1

			plots.append({
				"relativeWeight": 1,
				"trends": trends.values(),
				"axes": axes.values(),
				"markers": []
			})

		self.view.custom.plots = plots

		return

	if plotOption == 'auto':
		for item in itemInfo.values():
			pName = 'l{}'.format(item['log10'])

			if not pName in plotItemLists:
				plotItemLists[pName] = []

			plotItemLists[pName].append(item)

		for plotItems in plotItemLists.values():
			axes = {}
			trends = {}

			for item in plotItems:
				name = item['unit']

				min = item['min']
				max = item['max']

				label = item['label']
				unit = item['unit']
				color = colors[i]

				createAxis(name, min, max)

				createTrend(name, label, color)

				i += 1

			plots.append({
				"relativeWeight": 1,
				"trends": trends.values(),
				"axes": axes.values(),
				"markers": []
			})

		self.view.custom.plots = plots

		return

	if plotOption == 'test':
		for item in itemInfo.values():
			pName = '{}_l{}'.format(item['label'], '', item['log10'])

			if not pName in plotItemLists:
				plotItemLists[pName] = []

			plotItemLists[pName].append(item)

		for plotItems in plotItemLists.values():
			axes = {}
			trends = {}

			for item in plotItems:
				name = item['unit']

				min = item['min']
				max = item['max']

				label = item['label']
				unit = item['unit']
				color = colors[i]

				createAxis(name, min, max)

				createTrend(name, label, color)

				i += 1

			plots.append({
				"relativeWeight": 1,
				"trends": trends.values(),
				"axes": axes.values(),
				"markers": []
			})

		self.view.custom.plots = plots

		return

